reverse_bytes.go.src:
package main

import "fmt"

func reverse(s string) string {
	b := []byte(s)
	out := make([]byte, 0, len(b))
	for i := len(b) - 1; i >= 0; i-- {
		out = append(out, b[i])
	}
	return string(out)
}

func main() {
	fmt.Printf("%q\n", reverse("stop"))
	fmt.Printf("%q\n", reverse("héllo"))
}

reverse_runes.go.src:
package main

import "fmt"

func reverse(s string) string {
	r := []rune(s)
	out := make([]rune, 0, len(r))
	for i := len(r) - 1; i >= 0; i-- {
		out = append(out, r[i])
	}
	return string(out)
}

func main() {
	fmt.Printf("%q\n", reverse("stop"))
	fmt.Printf("%q\n", reverse("héllo"))
	fmt.Printf("%q\n", reverse("日本"))
}

