spot_reverse.go.src:
package main

import "fmt"

func backwards(s string) string {
	letters := []byte(s)
	out := ""
	for i := len(letters) - 1; i >= 0; i-- {
		out = out + string(letters[i])
	}
	return out
}

func main() {
	fmt.Println(backwards("año"))
}

